import type { RegistryList, RegistryListKey, RegistryPackage } from "./registry-source.types"

/** The line that tells a reader and the generator the file is not to be edited. */
const HEADER =
    "// Generated by scripts/build-plugin-registry.mjs. Do not edit: change the plugin packages in package.json or a package's lists, then run `node scripts/build-plugin-registry.mjs`."

/** The order of the lists in a part, and the capitalised word of an import alias. */
const KEYS: ReadonlyArray<RegistryListKey> = ["modules", "blocks", "nodes", "jobs", "entities"]

/** The alias an import of one list of one package gets: `part<index><Key>`. */
const aliasOf = (index: number, key: RegistryListKey): string =>
    `part${index}${key.charAt(0).toUpperCase()}${key.slice(1)}`

/** The list of a package for a key, when it exports one. */
const listOf = (entry: RegistryPackage, key: RegistryListKey): RegistryList | undefined =>
    entry.lists.find((list) => list.key === key)

/** One name of a package entry, imported under an alias. */
interface Binding {
    readonly from: string
    readonly name: string
    readonly alias: string
}

/** One `import { <name> as <alias>, ... } from "<from>"` per package entry, in the order the entries first occur. */
const importsOf = (bindings: ReadonlyArray<Binding>): ReadonlyArray<string> => {
    const froms = [...new Set(bindings.map((binding) => binding.from))]
    return froms.map((from) => {
        const names = bindings
            .filter((binding) => binding.from === from)
            .map((binding) => `${binding.name} as ${binding.alias}`)
        return `import { ${names.join(", ")} } from ${JSON.stringify(from)}`
    })
}

/**
 * The text of `packages/plugin-registry/src/installed.ts`: static imports of the lists of every installed package, and
 * `installed = defineInstallation([...parts], "<hash>")`. Every specifier is a string literal, so the bundler sees every package
 * at build time; the hash is the generator's literal. The caller formats the text.
 */
export const renderRegistrySource = (packages: ReadonlyArray<RegistryPackage>, registryHash: string): string => {
    const imports = importsOf(
        packages.flatMap((entry, index) =>
            KEYS.flatMap((key) => {
                const list = listOf(entry, key)
                return list === undefined ? [] : [{ from: list.from, name: list.name, alias: aliasOf(index, key) }]
            }),
        ),
    )
    const parts = packages.map((entry, index) => {
        const members = entry.lists.map((list) => list.key + ": " + aliasOf(index, list.key))
        return "{ " + members.join(", ") + " }"
    })
    return [
        HEADER,
        'import { defineInstallation } from "@nivo-lite/agent-sdk/installation"',
        'import type { Installation } from "@nivo-lite/agent-sdk/installation"',
        ...imports,
        "",
        "/** Everything installed: the lists of the core package and of every plugin package, joined and checked once at load. */",
        `export const installed: Installation = defineInstallation([${parts.join(", ")}], ${JSON.stringify(registryHash)})`,
        "",
    ].join("\n")
}

/**
 * The text of `packages/plugin-registry/src/client/blocks.ts`: one lazy renderer per installed block, whose component is loaded by a
 * static `import()` of its package's client entry the first time a spec draws it. A package with no renderers or no blocks adds none.
 */
export const renderClientSource = (packages: ReadonlyArray<RegistryPackage>): string => {
    const drawing = packages.flatMap((entry, index) => {
        const blocks = listOf(entry, "blocks")
        return entry.renderers === null || blocks === undefined ? [] : [{ index, blocks, renderers: entry.renderers }]
    })
    const imports = importsOf(
        drawing.map((entry) => ({
            from: entry.blocks.from,
            name: entry.blocks.name,
            alias: aliasOf(entry.index, "blocks"),
        })),
    )
    const loaders = drawing.map(
        (entry) =>
            `const load${entry.index} = (): Promise<ReadonlyArray<BlockRenderer>> =>\n    import(${JSON.stringify(entry.renderers.from)}).then((loaded) => loaded.${entry.renderers.name})`,
    )
    const spread = drawing.map(
        (entry) => `...${aliasOf(entry.index, "blocks")}.map((block) => lazyRenderer(block, load${entry.index}))`,
    )
    return [
        HEADER,
        'import { lazyRenderer } from "@nivo-lite/agent-sdk/client"',
        'import type { BlockRenderer } from "@nivo-lite/agent-sdk/client"',
        ...imports,
        "",
        ...loaders.flatMap((loader) => [loader, ""]),
        "/** The renderer of every installed block, each component downloaded when a spec first draws it. */",
        `export const blocks: ReadonlyArray<BlockRenderer> = [${spread.join(", ")}]`,
        "",
    ].join("\n")
}
